package com.bosslevels;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
		name = "Boss Levels",
		description = "Gives bosses fake XP and levels based on RuneLite KC",
		tags = {"boss", "xp", "levels"}
)
public class BossLevelsPlugin extends Plugin
{
	/* ===================== CONSTANTS ===================== */

	private static final String CONFIG_GROUP = "bosslevels";
	private static final Pattern KC_PATTERN =
			Pattern.compile("^Your (.+) kill count is: (\\d+)\\.$");
	private static final Pattern RL_KC_PREFIX_PATTERN =
			Pattern.compile("^(.+?):\\s*(.+?)\\s+kill count:\\s*(\\d+)\\s*$");
	private static final Pattern RL_KC_BODY_PATTERN =
			Pattern.compile("^(.+?)\\s+kill count:\\s*(\\d+)\\s*$");

	/* ===================== INJECTED ===================== */

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private OverlayManager overlayManager;
	@Inject private BossLevelsConfig config;

	@Provides
	BossLevelsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BossLevelsConfig.class);
	}

	/* ===================== STATE ===================== */

	private final Map<BossDefinition, Long> bossXp = new EnumMap<>(BossDefinition.class);
	private final Map<BossDefinition, Integer> bossLevels = new EnumMap<>(BossDefinition.class);
	private final Map<BossDefinition, Integer> lastKcSeen = new EnumMap<>(BossDefinition.class);

	// Pre-scaled icons
	private final Map<BossDefinition, BufferedImage> bossIcons16 = new EnumMap<>(BossDefinition.class);

	private int spotAnimKey = 1;

	/* ===================== PANEL UI ===================== */

	private BossLevelsPanel panel;
	private NavigationButton navButton;

	private void openBossDetail(BossDefinition boss)
	{
		if (panel == null)
		{
			return;
		}

		long xp = bossXp.getOrDefault(boss, 0L);
		int level = bossLevels.getOrDefault(boss, 1);

		int cur = xpForLevel(level);
		int nxt = xpForNextLevel(level);
		int pct = (level >= 99) ? 100 : (int) Math.floor(100.0 * (xp - cur) / Math.max(1, (nxt - cur)));

		BufferedImage icon = bossIcons16.get(boss);
		panel.showBoss(boss, xp, level, pct, icon);
	}

	/* ===================== XP DROP OVERLAY ===================== */

	private BossLevelsOverlay xpDropOverlay;

	/* ===================== STARTUP/SHUTDOWN ===================== */

	private BufferedImage pluginIcon;

	@Override
	protected void startUp()
	{
		pluginIcon = ImageUtil.loadImageResource(BossLevelsPlugin.class, "icons/plugin_icon.png");

		// Load XP + level state
		for (BossDefinition boss : BossDefinition.values())
		{
			long xp = loadLong(xpKey(boss), 0L);
			bossXp.put(boss, xp);
			bossLevels.put(boss, levelForXp(xp));
			lastKcSeen.put(boss, -1);
		}

		// Load icons
		bossIcons16.clear();
		for (BossDefinition boss : BossDefinition.values())
		{
			BufferedImage img = ImageUtil.loadImageResource(BossLevelsPlugin.class, "icons/" + boss.iconFile);
			if (img != null)
			{
				bossIcons16.put(boss, ImageUtil.resizeImage(img, 16, 16));
			}
		}

		// Panel
		panel = new BossLevelsPanel();
		panel.setOpenBossDetailConsumer(this::openBossDetail);

		navButton = NavigationButton.builder()
				.tooltip("Boss Levels")
				.icon(pluginIcon)
				.priority(5)
				.panel(panel)
				.build();

		SwingUtilities.invokeLater(() ->
		{
			clientToolbar.addNavigation(navButton);
			panel.rebuildOverview(bossXp, bossLevels, bossIcons16);
		});

		// XP overlay
		xpDropOverlay = new BossLevelsOverlay(client, this::colorForBoss, config, bossIcons16);
		overlayManager.add(xpDropOverlay);
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			SwingUtilities.invokeLater(() -> clientToolbar.removeNavigation(navButton));
		}
		navButton = null;
		panel = null;

		if (xpDropOverlay != null)
		{
			overlayManager.remove(xpDropOverlay);
			xpDropOverlay = null;
		}

		bossIcons16.clear();
	}

	/* ===================== CHAT HANDLER ===================== */

	@Subscribe
	@SuppressWarnings("unused")
	public void onChatMessage(ChatMessage event)
	{
		// Avoid ChatMessageType mismatches
		final String msg = Text.removeTags(event.getMessage()).trim();
		Matcher m = KC_PATTERN.matcher(msg);
		if (m.matches())
		{
			BossDefinition boss = findBossByKcName(m.group(1));
			if (boss != null)
			{
				applyKcUpdate(boss, Integer.parseInt(m.group(2)));
			}
			return;
		}

		m = RL_KC_PREFIX_PATTERN.matcher(msg);
		if (m.matches())
		{
			if (!isLocalPlayerName(m.group(1)))
			{
				return;
			}

			BossDefinition boss = findBossByKcName(m.group(2));
			if (boss != null)
			{
				applyKcUpdate(boss, Integer.parseInt(m.group(3)));
			}
			return;
		}

		m = RL_KC_BODY_PATTERN.matcher(msg);
		if (!m.matches())
		{
			return;
		}

		final String senderFromEvent = Text.removeTags(event.getName()).trim();
		if (!isLocalPlayerName(senderFromEvent))
		{
			return;
		}

		BossDefinition boss = findBossByKcName(m.group(1));
		if (boss != null)
		{
			applyKcUpdate(boss, Integer.parseInt(m.group(2)));
		}
	}

	private void applyKcUpdate(BossDefinition boss, int kc)
	{
		int previousKc = lastKcSeen.getOrDefault(boss, -1);
		int gainedKills = (previousKc == -1) ? 1 : (kc - previousKc);
		lastKcSeen.put(boss, kc);

		if (gainedKills <= 0)
		{
			return;
		}

		int oldLevel = bossLevels.getOrDefault(boss, 1);

		long newXp = (long) kc * boss.xpPerKill;
		int newLevel = levelForXp(newXp);

		bossXp.put(boss, newXp);
		bossLevels.put(boss, newLevel);
		saveLong(xpKey(boss), newXp);

		long gainedXp = (long) gainedKills * boss.xpPerKill;

		// Screen XP drop
		if (config.enableXpDrops() && xpDropOverlay != null)
		{
			xpDropOverlay.pushDrop(boss, gainedXp);
		}

		// Update panel and auto-open the boss that changed
		if (panel != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				panel.rebuildOverview(bossXp, bossLevels, bossIcons16);
				openBossDetail(boss);
			});
		}

		// Optional chat line
		if (config.enableChatLine())
		{
			client.addChatMessage(
					ChatMessageType.GAMEMESSAGE,
					"",
					"Boss Levels: " + boss.kcName + " +" + gainedXp +
							" xp (Total: " + newXp +
							", Level: " + newLevel + ")",
					null
			);
		}

		// Optional fireworks
		if (config.enableFireworks() && newLevel > oldLevel)
		{
			playLevelUpFireworks(newLevel);
		}
	}

	private boolean isLocalPlayerName(String sender)
	{
		Player p = client.getLocalPlayer();
		if (p == null || p.getName() == null)
		{
			return false;
		}
		return p.getName().trim().equalsIgnoreCase(sender.trim());
	}

	/* ===================== FIREWORKS ===================== */

	private void playLevelUpFireworks(int level)
	{
		final int anim = (level >= 99) ? SpotanimID.LEVELUP_99_ANIM : SpotanimID.LEVELUP_ANIM;

		clientThread.invoke(() ->
		{
			Player p = client.getLocalPlayer();
			if (p != null)
			{
				p.createSpotAnim(spotAnimKey++, anim, 0, 0);
			}
		});
	}

	/* ===================== XP CURVE ===================== */

	private static int levelForXp(long xp)
	{
		for (int level = 1; level < 99; level++)
		{
			if (xp < xpForLevel(level + 1))
			{
				return level;
			}
		}
		return 99;
	}

	private static int xpForLevel(int level)
	{
		double points = 0;
		for (int i = 1; i < level; i++)
		{
			points += Math.floor(i + 300.0 * Math.pow(2.0, i / 7.0));
		}
		return (int) Math.floor(points / 4.0);
	}

	private static int xpForNextLevel(int level)
	{
		if (level >= 99)
		{
			return xpForLevel(99);
		}
		return xpForLevel(level + 1);
	}

	/* ===================== CONFIG PERSISTENCE ===================== */

	private String xpKey(BossDefinition boss)
	{
		return "xp_" + boss.configKey;
	}

	private long loadLong(String key, long def)
	{
		String v = configManager.getConfiguration(CONFIG_GROUP, key);
		if (v == null)
		{
			return def;
		}

		try
		{
			return Long.parseLong(v);
		}
		catch (NumberFormatException e)
		{
			return def;
		}
	}

	private void saveLong(String key, long value)
	{
		configManager.setConfiguration(CONFIG_GROUP, key, Long.toString(value));
	}

	/* ===================== HELPERS ===================== */

	private BossDefinition findBossByKcName(String name)
	{
		String normalized = name == null ? "" : name.trim();
		for (BossDefinition boss : BossDefinition.values())
		{
			if (boss.kcName.equalsIgnoreCase(normalized))
			{
				return boss;
			}
		}
		return null;
	}

	private Color colorForBoss(BossDefinition boss)
	{
		if (config.colorMode() == BossLevelsConfig.ColorMode.GLOBAL)
		{
			return config.globalXpColor();
		}

		float hue = (boss.ordinal() * 0.21f) % 1.0f;
		Color base = Color.getHSBColor(hue, 0.70f, 1.0f);
		int a = config.globalXpColor().getAlpha();
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), a);
	}
}

package com.bosslevels;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup("bosslevels")
public interface BossLevelsConfig extends Config
{
    @ConfigSection(
            name = "XP Drops",
            description = "XP drop visuals",
            position = 0
    )
    String xpSection = "xpSection";

    @ConfigSection(
            name = "Notifications",
            description = "Chat + fireworks",
            position = 1
    )
    String notifSection = "notifSection";

    // ---------- XP Drops toggles ----------
    @ConfigItem(
            keyName = "enableXpDrops",
            name = "Enable XP drops",
            description = "Show boss XP drops on screen",
            position = 0,
            section = xpSection
    )
    default boolean enableXpDrops() { return true; }

    @ConfigItem(
            keyName = "showBossNameInDrop",
            name = "Show boss name in drop",
            description = "Include the boss name in the XP drop text",
            position = 1,
            section = xpSection
    )
    default boolean showBossNameInDrop() { return false; }

    @ConfigItem(
            keyName = "showBossMarker",
            name = "Show boss marker",
            description = "Draw a small colored marker next to the XP drop (acts like an icon)",
            position = 2,
            section = xpSection
    )
    default boolean showBossMarker() { return true; }

    public enum ColorMode { GLOBAL, PER_BOSS }

    @ConfigItem(
            keyName = "colorMode",
            name = "Color mode",
            description = "Use one global color, or a unique deterministic color per boss",
            position = 3,
            section = xpSection
    )
    default ColorMode colorMode() { return ColorMode.GLOBAL; }

    @Alpha
    @ConfigItem(
            keyName = "globalXpColor",
            name = "Global XP color",
            description = "Color used when Color mode = GLOBAL",
            position = 4,
            section = xpSection
    )
    default Color globalXpColor() { return new Color(255, 200, 0, 255); }

    @Range(min = 1, max = 12)
    @ConfigItem(
            keyName = "maxVisibleDrops",
            name = "Max visible drops",
            description = "How many XP drops can be visible at once",
            position = 5,
            section = xpSection
    )
    default int maxVisibleDrops() { return 6; }

    // ---------- Motion / timing ----------
    @Range(min = 300, max = 5000)
    @ConfigItem(
            keyName = "durationMs",
            name = "Drop duration (ms)",
            description = "How long each XP drop lasts (controls speed)",
            position = 6,
            section = xpSection
    )
    default int durationMs() { return 1600; }

    @ConfigItem(
            keyName = "startX",
            name = "Start X (px)",
            description = "Start position X in pixels from the top-left of the game canvas",
            position = 7,
            section = xpSection
    )
    default int startX() { return 470; }

    @ConfigItem(
            keyName = "startY",
            name = "Start Y (px)",
            description = "Start position Y in pixels from the top-left of the game canvas",
            position = 8,
            section = xpSection
    )
    default int startY() { return 35; }

    @ConfigItem(
            keyName = "endX",
            name = "End X (px)",
            description = "End position X in pixels from the top-left of the game canvas",
            position = 9,
            section = xpSection
    )
    default int endX() { return 470; }

    @ConfigItem(
            keyName = "endY",
            name = "End Y (px)",
            description = "End position Y in pixels from the top-left of the game canvas",
            position = 10,
            section = xpSection
    )
    default int endY() { return 5; }

    @Range(min = 0, max = 30)
    @ConfigItem(
            keyName = "stackSpacing",
            name = "Stack spacing (px)",
            description = "Vertical spacing between stacked XP drops",
            position = 11,
            section = xpSection
    )
    default int stackSpacing() { return 14; }

    // ---------- Combine drops ----------
    @ConfigItem(
            keyName = "combineDrops",
            name = "Combine drops",
            description = "Combine multiple drops into one (like OSRS XP drops)",
            position = 12,
            section = xpSection
    )
    default boolean combineDrops() { return true; }

    @Range(min = 50, max = 1500)
    @ConfigItem(
            keyName = "combineWindowMs",
            name = "Combine window (ms)",
            description = "If a new drop happens within this window, it merges into the latest drop",
            position = 13,
            section = xpSection
    )
    default int combineWindowMs() { return 450; }

    // ---------- Notifications ----------
    @ConfigItem(
            keyName = "enableChatLine",
            name = "Chat message",
            description = "Print the Boss Levels line in chat",
            position = 0,
            section = notifSection
    )
    default boolean enableChatLine() { return true; }

    @ConfigItem(
            keyName = "enableFireworks",
            name = "Level-up fireworks",
            description = "Play the in-game level-up fireworks on boss level-up",
            position = 1,
            section = notifSection
    )
    default boolean enableFireworks() { return true; }
}

package com.bosslevels;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Image;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

public class BossLevelsPanel extends PluginPanel
{
    private final CardLayout cardLayout = new CardLayout();
    private final JPanel root = new JPanel(cardLayout);

    // Overview (grid)
    private final JPanel grid = new JPanel();
    private final JScrollPane gridScroll;

    // Detail
    private final JPanel detail = new JPanel(new BorderLayout());
    private final JButton backButton = new JButton("Back");
    private final JLabel detailTitle = new JLabel();
    private final JLabel detailXp = new JLabel();
    private final JLabel detailPct = new JLabel();
    private final JTextArea milestonesArea = new JTextArea();

    private final NumberFormat nf = NumberFormat.getInstance();

    private BossDefinition selectedBoss = null;
    private Consumer<BossDefinition> onBossClicked = boss -> {};

    public BossLevelsPanel()
    {
        setLayout(new BorderLayout());
        add(root, BorderLayout.CENTER);

        /* ---------- Overview card ---------- */
        grid.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        grid.setLayout(new GridLayout(0, 3, 18, 18));

        JPanel gridWrapper = new JPanel(new BorderLayout());
        gridWrapper.setOpaque(false);
        gridWrapper.add(grid, BorderLayout.NORTH); // pin grid to top

        gridScroll = new JScrollPane(gridWrapper);
        gridScroll.setBorder(null);

        root.add(gridScroll, "overview");

        /* ---------- Detail card ---------- */
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setOpaque(false);

        // Row 1: title (full width)
        detailTitle.setFont(detailTitle.getFont().deriveFont(Font.BOLD, 16f));
        detailTitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(detailTitle);

        // Row 2: xp + % (next line)
        JPanel statsRow = new JPanel(new BorderLayout());
        statsRow.setOpaque(false);
        statsRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        detailXp.setHorizontalAlignment(SwingConstants.LEFT);
        detailPct.setHorizontalAlignment(SwingConstants.RIGHT);

        statsRow.add(detailXp, BorderLayout.WEST);
        statsRow.add(detailPct, BorderLayout.EAST);

        header.add(Box.createVerticalStrut(2));
        header.add(statsRow);

        JPanel topRow = new JPanel(new BorderLayout());
        topRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
        topRow.add(backButton, BorderLayout.WEST);

        JPanel topWrap = new JPanel();
        topWrap.setLayout(new BoxLayout(topWrap, BoxLayout.Y_AXIS));
        topWrap.setBorder(BorderFactory.createEmptyBorder(8, 0, 8, 0));
        topWrap.add(topRow);
        topWrap.add(header);

        milestonesArea.setEditable(false);
        milestonesArea.setLineWrap(true);
        milestonesArea.setWrapStyleWord(true);
        milestonesArea.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
        milestonesArea.setOpaque(false);

        JScrollPane milestonesScroll = new JScrollPane(milestonesArea);
        milestonesScroll.setBorder(null);

        detail.add(topWrap, BorderLayout.NORTH);
        detail.add(milestonesScroll, BorderLayout.CENTER);

        root.add(detail, "detail");

        backButton.addActionListener(e -> showOverview());
        showOverview();
    }
    public void setOpenBossDetailConsumer(Consumer<BossDefinition> onBossClicked)
    {
        this.onBossClicked = (onBossClicked != null) ? onBossClicked : boss -> {};
    }

    public void showOverview()
    {
        selectedBoss = null;
        cardLayout.show(root, "overview");
        SwingUtilities.invokeLater(() -> gridScroll.getVerticalScrollBar().setValue(0));
    }

    public void showBoss(
            BossDefinition boss,
            long xp,
            int level,
            int pct,
            BufferedImage icon
    )
    {
        selectedBoss = boss;

        // Title: icon + name + level
        if (icon != null)
        {
            Image scaled = icon.getScaledInstance(20, 20, Image.SCALE_SMOOTH);
            detailTitle.setIcon(new ImageIcon(scaled));
            detailTitle.setIconTextGap(6);
        }
        else
        {
            detailTitle.setIcon(null);
        }

        detailTitle.setText("<html>" + boss.kcName + " — Lvl " + level + "</html>");
        detailXp.setText(nf.format(xp) + " xp");
        detailPct.setText(pct + "%");
        detailTitle.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < boss.milestones.size(); i++)
        {
            sb.append(boss.milestones.get(i));
            if (i < boss.milestones.size() - 1)
            {
                sb.append("\n\n");
            }
        }
        milestonesArea.setText(sb.toString().trim());

        cardLayout.show(root, "detail");
    }
    public void rebuildOverview(
            Map<BossDefinition, Long> xpMap,
            Map<BossDefinition, Integer> levelMap,
            Map<BossDefinition, BufferedImage> iconMap
    )
    {
        rebuildOverview(xpMap, levelMap, iconMap, onBossClicked);
    }
    public void rebuildOverview(
            Map<BossDefinition, Long> xpMap,
            Map<BossDefinition, Integer> levelMap,
            Map<BossDefinition, BufferedImage> iconMap,
            Consumer<BossDefinition> onBossClicked
    )
    {
        this.onBossClicked = (onBossClicked != null) ? onBossClicked : boss -> {};

        grid.removeAll();

        for (BossDefinition boss : BossDefinition.values())
        {
            int level = levelMap.getOrDefault(boss, 1);
            long xp = xpMap.getOrDefault(boss, 0L);

            // show "--" if XP is 0
            String levelText = (xp <= 0) ? "--" : String.valueOf(level);

            BufferedImage icon = iconMap.get(boss);
            JLabel iconLabel = new JLabel();
            if (icon != null)
            {
                Image scaled = icon.getScaledInstance(19, 19, Image.SCALE_SMOOTH);
                iconLabel.setIcon(new ImageIcon(scaled));
            }

            JLabel levelLabel = new JLabel(levelText, SwingConstants.CENTER);
            levelLabel.setForeground(Color.LIGHT_GRAY);

            JPanel cell = new JPanel();
            cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));
            cell.setOpaque(false);

            iconLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            levelLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

            cell.add(iconLabel);
            cell.add(Box.createVerticalStrut(6));
            cell.add(levelLabel);

            cell.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e)
                {
                    BossLevelsPanel.this.onBossClicked.accept(boss);
                }

                @Override
                public void mouseEntered(MouseEvent e)
                {
                    cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                }
            });

            grid.add(cell);
        }

        grid.revalidate();
        grid.repaint();
    }
}

package com.bosslevels;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

@FunctionalInterface
interface BossColorProvider
{
    Color get(BossDefinition boss);
}

public class BossLevelsOverlay extends Overlay
{
    private static class Drop
    {
        BossDefinition boss;
        long xp;
        long startMs;

        Drop(BossDefinition boss, long xp, long startMs)
        {
            this.boss = boss;
            this.xp = xp;
            this.startMs = startMs;
        }
    }

    private final Client client;
    private final BossColorProvider colorProvider;
    private final BossLevelsConfig config;
    private final Map<BossDefinition, BufferedImage> iconMap16;

    private final Deque<Drop> drops = new ArrayDeque<>();

    public BossLevelsOverlay(
            Client client,
            BossColorProvider colorProvider,
            BossLevelsConfig config,
            Map<BossDefinition, BufferedImage> iconMap16
    )
    {
        this.client = client;
        this.colorProvider = colorProvider;
        this.config = config;
        this.iconMap16 = iconMap16;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(OverlayPriority.HIGH);
    }

    void pushDrop(BossDefinition boss, long gainedXp)
    {
        long now = System.currentTimeMillis();

        if (config.combineDrops() && !drops.isEmpty())
        {
            Drop latest = drops.peekFirst();
            if (latest != null && (now - latest.startMs) <= config.combineWindowMs())
            {
                latest.xp += gainedXp;
                latest.boss = boss;
                return;
            }
        }

        drops.addFirst(new Drop(boss, gainedXp, now));
        while (drops.size() > config.maxVisibleDrops())
        {
            drops.removeLast();
        }
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.enableXpDrops())
        {
            drops.clear();
            return null;
        }

        Rectangle canvas = client.getCanvas().getBounds();
        if (canvas == null)
        {
            return null;
        }

        long now = System.currentTimeMillis();
        int duration = Math.max(1, config.durationMs());

        drops.removeIf(d -> now - d.startMs > duration);

        int sx = clamp(config.startX(), 0, canvas.width);
        int sy = clamp(config.startY(), 0, canvas.height);
        int ex = clamp(config.endX(), 0, canvas.width);
        int ey = clamp(config.endY(), 0, canvas.height);

        double vx = ex - sx;
        double vy = ey - sy;

        double len = Math.sqrt(vx * vx + vy * vy);
        double px = (len == 0) ? 0 : (-vy / len);
        double py = (len == 0) ? 1 : (vx / len);

        g.setFont(g.getFont().deriveFont(Font.BOLD, 14f));

        int idx = 0;
        for (Drop d : drops)
        {
            float t = (now - d.startMs) / (float) duration;
            t = clamp01(t);

            // ease-out
            float eased = 1f - (float) Math.pow(1f - t, 2);

            int x = (int) Math.round(sx + vx * eased);
            int y = (int) Math.round(sy + vy * eased);

            int spacing = Math.max(0, config.stackSpacing());
            x += (int) Math.round(px * idx * spacing);
            y += (int) Math.round(py * idx * spacing);

            float alpha = 1f - t;
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

            Color color = colorProvider.get(d.boss);

            String text = "+" + d.xp;
            if (config.showBossNameInDrop())
            {
                text = d.boss.kcName + " " + text;
            }

            int iconSize = 16;
            int iconGap = 6;
            int textX = x;

            if (config.showBossMarker())
            {
                BufferedImage icon = iconMap16.get(d.boss);
                if (icon != null)
                {
                    FontMetrics fm = g.getFontMetrics();
                    int ascent = fm.getAscent();
                    int textTop = y - ascent;
                    int iconY = textTop + Math.max(0, (ascent - iconSize) / 2);

                    g.drawImage(icon, x, iconY, null);
                    textX = x + iconSize + iconGap;
                }
            }

            // shadow
            g.setColor(new Color(0, 0, 0, Math.min(255, color.getAlpha())));
            g.drawString(text, textX + 1, y + 1);

            // main
            g.setColor(color);
            g.drawString(text, textX, y);

            idx++;
        }

        g.setComposite(AlphaComposite.SrcOver);
        return null;
    }

    private static int clamp(int v, int lo, int hi)
    {
        return Math.max(lo, Math.min(hi, v));
    }

    private static float clamp01(float v)
    {
        return Math.max(0f, Math.min(1f, v));
    }
}
